//! PROV-O export for provenance records (SDP §14.2).
//!
//! Maps an Aether `ProvenanceRecord` to standard PROV-O RDF terms:
//! - `prov:Entity`           — an artifact (input or output)
//! - `prov:Activity`         — the production event
//! - `prov:Agent`            — the actor and the tool
//! - `prov:wasGeneratedBy`   — artifact was generated by the activity
//! - `prov:used`             — activity used the input
//! - `prov:wasAttributedTo`  — artifact was attributed to the actor
//! - `prov:wasDerivedFrom`   — output was derived from input
//!
//! The export produces a JSON-LD document (Phase 0; full Turtle export
//! arrives in G2 when the conformance suite adds the
//! `prov:Bundle` wrapper).

#![deny(unsafe_code)]

use serde::{Deserialize, Serialize};
use thiserror::Error;
use uuid::Uuid;

use crate::record::ProvenanceRecord;

#[derive(Debug, Error)]
pub enum ProvOError {
    #[error("record has no outputs to export")]
    NoOutputs,
}

pub type ProvOResult<T> = Result<T, ProvOError>;

/// A minimal JSON-LD document with the PROV-O terms the platform uses.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProvODocument {
    #[serde(rename = "@context")]
    pub context: ProvOContext,
    #[serde(rename = "@graph")]
    pub graph: Vec<ProvONode>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ProvOContext {
    pub prov: String,
    pub aether: String,
    pub rdfs: String,
    pub xsd: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "@type")]
pub enum ProvONode {
    #[serde(rename = "prov:Entity")]
    Entity { id: String, label: String, cas_hash: String },
    #[serde(rename = "prov:Activity")]
    Activity {
        id: String,
        started_at: String,
        ended_at: String,
    },
    #[serde(rename = "prov:Agent")]
    Agent { id: String, role: String },
    #[serde(rename = "prov:SoftwareAgent")]
    SoftwareAgent { id: String, plugin_id: String, plugin_version: String },
    #[serde(rename = "prov:Usage")]
    Usage { id: String, activity: String, entity: String },
    #[serde(rename = "prov:Generation")]
    Generation { id: String, activity: String, entity: String },
    #[serde(rename = "prov:Attribution")]
    Attribution { id: String, entity: String, agent: String },
}

/// Convert a record to a PROV-O document. The returned graph contains one
/// `Activity`, one `SoftwareAgent` (the tool), one `Agent` (the actor),
/// one entity per input and output, and the `Usage`/`Generation`/
/// `Attribution` edges that wire them together.
pub fn prov_o_record(record: &ProvenanceRecord) -> ProvOResult<ProvODocument> {
    if record.outputs.is_empty() {
        return Err(ProvOError::NoOutputs);
    }
    let activity_id = format!("aether:activity:{}", record.record_id);
    let tool_id = format!(
        "aether:agent:{}@{}",
        record.tool.plugin_id, record.tool.plugin_version
    );
    let actor_id = format!("aether:agent:{}", record.actor.id);

    let mut graph = Vec::new();
    graph.push(ProvONode::Activity {
        id: activity_id.clone(),
        started_at: record.produced_at.clone(),
        ended_at: record.produced_at.clone(),
    });
    graph.push(ProvONode::SoftwareAgent {
        id: tool_id.clone(),
        plugin_id: record.tool.plugin_id.clone(),
        plugin_version: record.tool.plugin_version.clone(),
    });
    let role = record
        .actor
        .role
        .clone()
        .unwrap_or_else(|| "unspecified".to_string());
    graph.push(ProvONode::Agent {
        id: actor_id.clone(),
        role,
    });
    let mut counter: u32 = 0;
    let mut next_id = || {
        counter += 1;
        format!("aether:edge:{}:{}", record.record_id, counter)
    };
    for input in &record.inputs {
        let entity_id = format!("aether:entity:{}", input.cas_hash);
        graph.push(ProvONode::Entity {
            id: entity_id.clone(),
            label: input.name.clone(),
            cas_hash: input.cas_hash.clone(),
        });
        graph.push(ProvONode::Usage {
            id: next_id(),
            activity: activity_id.clone(),
            entity: entity_id,
        });
    }
    for output in &record.outputs {
        let entity_id = format!("aether:entity:{}", output.cas_hash);
        graph.push(ProvONode::Entity {
            id: entity_id.clone(),
            label: output.name.clone(),
            cas_hash: output.cas_hash.clone(),
        });
        graph.push(ProvONode::Generation {
            id: next_id(),
            activity: activity_id.clone(),
            entity: entity_id.clone(),
        });
        graph.push(ProvONode::Attribution {
            id: next_id(),
            entity: entity_id,
            agent: tool_id.clone(),
        });
    }
    Ok(ProvODocument {
        context: ProvOContext {
            prov: "http://www.w3.org/ns/prov#".to_string(),
            aether: "https://aether.local/ns/".to_string(),
            rdfs: "http://www.w3.org/2000/01/rdf-schema#".to_string(),
            xsd: "http://www.w3.org/2001/XMLSchema#".to_string(),
        },
        graph,
    })
}

/// Convenience: build a `ProvODocument` from a record by reference id.
pub fn prov_o_for_record_id(
    record: &ProvenanceRecord,
    _id: Uuid,
) -> ProvOResult<ProvODocument> {
    prov_o_record(record)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::record::{Actor, ArtifactRef, AuthorizationDecision, ProvenanceRecord, ToolRef};

    fn sample() -> ProvenanceRecord {
        ProvenanceRecord::new(
            Actor {
                id: "user:alice".to_string(),
                role: Some("analyst".to_string()),
                plugin_instance: None,
            },
            AuthorizationDecision {
                decision: "allow".to_string(),
                policy_ref: None,
                rationale: None,
            },
            ToolRef {
                plugin_id: "com.example.solver".to_string(),
                plugin_version: "1.0.0".to_string(),
                contract_versions: Default::default(),
                conformance_report: None,
            },
            vec![ArtifactRef {
                cas_hash: "1".repeat(64),
                name: "geometry".to_string(),
                size: 0,
                format: None,
            }],
            vec![ArtifactRef {
                cas_hash: "2".repeat(64),
                name: "result".to_string(),
                size: 0,
                format: None,
            }],
            None,
        )
    }

    #[test]
    fn export_includes_activity_agent_entities() {
        let r = sample();
        let doc = prov_o_record(&r).expect("export");
        // 1 activity + 1 software agent + 1 agent + 2 entities +
        // 1 usage (input) + 1 generation + 1 attribution (output) = 8
        assert_eq!(doc.graph.len(), 8);
    }

    #[test]
    fn export_without_outputs_errors() {
        let mut r = sample();
        r.outputs.clear();
        let err = prov_o_record(&r).unwrap_err();
        assert!(matches!(err, ProvOError::NoOutputs));
    }
}
